/**
 * «آية وحديث» engine — one bundled, offline corpus (≈٧٥٠ hadith + ≈٦٧٠ ayat,
 * generated by scripts/gen-inspiration.mjs from hadith-api + quran.com) and
 * the picking rules shared by the Home card, the library page and the
 * notification planner.
 *
 * Picks are DAY-APPROPRIATE: the Hijri date (offline, Umm al-Qura via Intl)
 * and the weekday map to preferred tags (رمضان → صيام/قرآن، الجمعة → جمعة/الكهف…);
 * `strength` is the share of picks drawn from the matching pool, so ordinary
 * content still appears on special days. Everything else is seeded random,
 * which keeps "of the day" stable per dateKey and a planned notification slot
 * stable across re-plans.
 */
import { specialDayFor } from '@/data/specialIslamicDays';
import { toArabicDigits } from '@/utils/arabicFormat';

export type InspirationKind = 'ayah' | 'hadith';

export interface InspirationItem {
  kind: InspirationKind;
  /** 'ara-bukhari_13' | 'ayah_2:255' */
  id: string;
  text: string;
  /** Book name, or 'سورة البقرة' for an ayah. */
  book: string;
  number: number;
  /** Verse key for ayat ('2:255', or a passage '94:1-8'). */
  key?: string;
  /** Last ayah of a passage. */
  ayahEnd?: number;
  grade?: 'sahih' | 'hasan';
  tags: string[];
}

interface RawHadith { id: string; text: string; book: string; number: number; grade?: 'sahih' | 'hasan'; tags: string[] }
interface RawAyah { key: string; text: string; surah: string; ayah: number; ayahEnd?: number; tags: string[] }

let corpus: InspirationItem[] | null = null;
let loading: Promise<InspirationItem[]> | null = null;

export function buildCorpus(hadith: RawHadith[], ayat: RawAyah[]): InspirationItem[] {
  return [
    ...ayat.map<InspirationItem>((a) => ({
      kind: 'ayah',
      id: `ayah_${a.key}`,
      key: a.key,
      text: a.text,
      book: `سورة ${a.surah}`,
      number: a.ayah,
      ...(a.ayahEnd ? { ayahEnd: a.ayahEnd } : {}),
      tags: a.tags,
    })),
    ...hadith.map<InspirationItem>((h) => ({ kind: 'hadith', ...h })),
  ];
}

/** Lazy-load the corpus (two JSON chunks, kept out of the initial bundle). */
export function loadCorpus(): Promise<InspirationItem[]> {
  loading ??= Promise.all([
    import('@/data/inspiration/hadith.json'),
    import('@/data/inspiration/ayat.json'),
  ]).then(([h, a]) => {
    corpus = buildCorpus(h.default as RawHadith[], a.default as RawAyah[]);
    return corpus;
  });
  return loading;
}

export const getCorpusSync = (): InspirationItem[] | null => corpus;
export const findItem = (items: InspirationItem[], id: string) => items.find((i) => i.id === id);

// ─── Display helpers ───────────────────────────────────────────────────────

export const isQudsi = (i: InspirationItem) => i.tags.includes('قدسي');

/** «صحيح البخاري · رقم ١٣» / «سورة البقرة · ٢٥٥» */
export function sourceLine(i: InspirationItem): string {
  if (!i.number) return i.book; // legacy favourite saved without a number
  if (i.kind === 'hadith') return `${i.book} · رقم ${toArabicDigits(i.number)}`;
  return `${i.book} · ${toArabicDigits(i.number)}${i.ayahEnd ? `–${toArabicDigits(i.ayahEnd)}` : ''}`;
}

/** Ayat already carry their «﴿n﴾» verse markers; hadith get guillemets. */
export const displayText = (i: InspirationItem) => (i.kind === 'ayah' ? i.text : `«${i.text}»`);

export function shareText(i: InspirationItem): string {
  return `${displayText(i)}\n— ${sourceLine(i)}`;
}

/** Arabic search form: no harakat/Quranic marks/tatweel; unified alif/ya/ta-marbuta/hamza seats. */
export function normalizeArabic(s: string): string {
  return s
    .replace(/[\u0610-\u061A\u064B-\u065F\u0670\u06D6-\u06ED\u0640]/g, '')
    .replace(/[أإآٱ]/g, 'ا')
    .replace(/ى/g, 'ي')
    .replace(/ة/g, 'ه')
    .replace(/ؤ/g, 'و')
    .replace(/ئ/g, 'ي')
    .replace(/\s+/g, ' ')
    .trim();
}

const normCache = new WeakMap<InspirationItem, string>();
export function searchItems(items: InspirationItem[], query: string): InspirationItem[] {
  const q = normalizeArabic(query);
  if (!q) return items;
  const words = q.split(' ');
  return items.filter((i) => {
    let n = normCache.get(i);
    if (n === undefined) {
      n = normalizeArabic(`${i.text} ${i.book}`);
      normCache.set(i, n);
    }
    return words.every((w) => n!.includes(w));
  });
}

// ─── Day context ───────────────────────────────────────────────────────────

export interface DayContext {
  /** Preferred tags, most specific first. */
  tags: string[];
  /** Short Arabic occasion name for titles ('يوم الجمعة', 'يوم عرفة'…). */
  label?: string;
  /** 0..1 — share of picks taken from the tag-matching pool. */
  strength: number;
}

export function hijriOf(date: Date): { day: number; month: number } | null {
  try {
    const parts = new Intl.DateTimeFormat('en-u-ca-islamic-umalqura', { day: 'numeric', month: 'numeric' }).formatToParts(date);
    const day = Number(parts.find((p) => p.type === 'day')?.value);
    const month = Number(parts.find((p) => p.type === 'month')?.value);
    return Number.isFinite(day) && Number.isFinite(month) ? { day, month } : null;
  } catch {
    return null;
  }
}

export function dayContext(date: Date): DayContext {
  const h = hijriOf(date);
  const special = h ? specialDayFor(h.month, h.day)?.nameAr : undefined;
  let ctx: DayContext = { tags: [], strength: 0 };
  if (h) {
    const { month: m, day: d } = h;
    if (m === 9) {
      ctx = d >= 20
        ? { tags: ['ليلة القدر', 'قيام', 'دعاء', 'رمضان', 'قرآن'], label: special ?? 'العشر الأواخر', strength: 0.8 }
        : { tags: ['رمضان', 'صيام', 'قرآن', 'قيام'], label: special ?? 'شهر رمضان', strength: 0.75 };
    } else if (m === 10 && d === 1) ctx = { tags: ['عيد', 'شكر', 'ذكر'], label: special, strength: 0.75 };
    else if (m === 12 && d === 9) ctx = { tags: ['عشر ذي الحجة', 'دعاء', 'حج'], label: special, strength: 0.85 };
    else if (m === 12 && d === 10) ctx = { tags: ['عيد', 'عشر ذي الحجة', 'حج', 'ذكر'], label: special, strength: 0.8 };
    else if (m === 12 && d <= 8) ctx = { tags: ['عشر ذي الحجة', 'ذكر', 'حج', 'صيام'], label: 'عشر ذي الحجة', strength: 0.7 };
    else if (m === 12 && d <= 13) ctx = { tags: ['ذكر', 'عيد', 'حج'], label: special, strength: 0.6 };
    else if (m === 1 && (d === 9 || d === 10)) ctx = { tags: ['عاشوراء', 'صيام', 'صبر'], label: special, strength: 0.8 };
    else if (m === 1 && d === 1) ctx = { tags: ['هجرة', 'توبة'], label: special, strength: 0.7 };
    else if (m === 1) ctx = { tags: ['صيام', 'هجرة'], strength: 0.3 };
    else if (m === 8 && d === 15) ctx = { tags: ['صيام', 'توبة', 'دعاء'], label: special, strength: 0.5 };
    else if (m === 8) ctx = { tags: ['صيام', 'رمضان'], strength: 0.25 };
    else if (d >= 13 && d <= 15) ctx = { tags: ['صيام'], strength: 0.3 };
  }
  const wd = date.getDay();
  if (wd === 5) {
    ctx = {
      tags: [...ctx.tags, 'جمعة', 'الصلاة على النبي', 'دعاء'].filter((t, i, a) => a.indexOf(t) === i),
      label: ctx.label ?? 'يوم الجمعة',
      strength: Math.max(ctx.strength, 0.6),
    };
  } else if (wd === 1 || wd === 4) {
    ctx = { ...ctx, tags: ctx.tags.includes('صيام') ? ctx.tags : [...ctx.tags, 'صيام'], strength: Math.max(ctx.strength, 0.3) };
  }
  return ctx;
}

// ─── Seeded picking ────────────────────────────────────────────────────────

export function hashSeed(s: string): number {
  let h = 2166136261 >>> 0;
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619);
  return h >>> 0;
}

/** mulberry32 */
export function seededRandom(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export interface PickOptions {
  kind?: InspirationKind;
  /** Drop very long texts (home card / notifications). */
  maxLen?: number;
  exclude?: Set<string>;
}

/** Weighted pick: `ctx.strength` of the time from the tag-matching pool, avoiding `exclude`. */
export function pickSeeded(items: InspirationItem[], ctx: DayContext, rand: () => number, opts: PickOptions = {}): InspirationItem | null {
  let pool = items.filter((i) => (!opts.kind || i.kind === opts.kind) && (!opts.maxLen || i.text.length <= opts.maxLen));
  if (pool.length === 0) return null;
  if (ctx.tags.length && rand() < ctx.strength) {
    // The first (most specific) tag gets half of the matching draws.
    const primary = pool.filter((i) => i.tags.includes(ctx.tags[0]));
    const any = pool.filter((i) => i.tags.some((t) => ctx.tags.includes(t)));
    const matching = primary.length && rand() < 0.5 ? primary : any;
    if (matching.length) pool = matching;
  }
  if (opts.exclude?.size) {
    const fresh = pool.filter((i) => !opts.exclude!.has(i.id));
    if (fresh.length) pool = fresh;
  }
  return pool[Math.floor(rand() * pool.length)];
}

export const dateKeyOf = (d: Date) =>
  `${d.getFullYear()}${String(d.getMonth() + 1).padStart(2, '0')}${String(d.getDate()).padStart(2, '0')}`;

/** Deterministic, day-appropriate "آية/حديث اليوم". */
export function pickForDay(items: InspirationItem[], date: Date, kind: InspirationKind): InspirationItem | null {
  return pickSeeded(items, dayContext(date), seededRandom(hashSeed(`${dateKeyOf(date)}:${kind}`)), { kind, maxLen: 450 });
}

// ─── Recently-seen ring (device-local; keeps shuffles + notifications fresh) ─

const RECENT_KEY = 'myzikr:inspiration-recent';
const RECENT_MAX = 150;

export function getRecent(): string[] {
  try {
    const v = JSON.parse(localStorage.getItem(RECENT_KEY) ?? '[]');
    return Array.isArray(v) ? v.filter((x) => typeof x === 'string') : [];
  } catch {
    return [];
  }
}

export function markSeen(ids: string[]): void {
  if (ids.length === 0) return;
  const next = [...getRecent().filter((x) => !ids.includes(x)), ...ids].slice(-RECENT_MAX);
  try {
    localStorage.setItem(RECENT_KEY, JSON.stringify(next));
  } catch {
    /* quota — freshness is best-effort */
  }
}

/** A fresh random item (shuffle), day-aware, avoiding the recent ring; records it as seen. */
export function pickRandom(items: InspirationItem[], opts: PickOptions & { date?: Date } = {}): InspirationItem | null {
  const exclude = new Set([...getRecent(), ...(opts.exclude ?? [])]);
  const picked = pickSeeded(items, dayContext(opts.date ?? new Date()), Math.random, { ...opts, exclude });
  if (picked) markSeen([picked.id]);
  return picked;
}
